import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;

public class ReportsFrame extends JFrame {
    private final DefaultTableModel model=new DefaultTableModel(); private final JTable table=new JTable(model);
    public ReportsFrame(){setTitle("Reports");setSize(760,430);setLocationRelativeTo(null);JPanel p=new JPanel();JButton most=new JButton("Most Booked");JButton current=new JButton("Currently Borrowed");JButton overdue=new JButton("Overdue");JButton cat=new JButton("Bookings by Category");p.add(most);p.add(current);p.add(overdue);p.add(cat);add(p,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);most.addActionListener(e->query("SELECT e.equipment_name AS Equipment,COALESCE(SUM(b.quantity),0) AS Total_Booked FROM equipment e LEFT JOIN bookings b ON e.equipment_id=b.equipment_id AND b.status IN ('Approved','Returned') GROUP BY e.equipment_id,e.equipment_name ORDER BY Total_Booked DESC"));current.addActionListener(e->query("SELECT u.name AS Student,e.equipment_name AS Equipment,b.quantity AS Quantity,b.return_date AS Return_Date FROM bookings b JOIN users u ON b.user_id=u.user_id JOIN equipment e ON b.equipment_id=e.equipment_id WHERE b.status='Approved'"));overdue.addActionListener(e->query("SELECT u.name AS Student,e.equipment_name AS Equipment,b.return_date AS Due_Date,DATEDIFF(CURDATE(),b.return_date) AS Days_Overdue FROM bookings b JOIN users u ON b.user_id=u.user_id JOIN equipment e ON b.equipment_id=e.equipment_id WHERE b.status='Approved' AND b.return_date<CURDATE()"));cat.addActionListener(e->query("SELECT c.category_name AS Category,COUNT(b.booking_id) AS Bookings FROM categories c LEFT JOIN equipment e ON c.category_id=e.category_id LEFT JOIN bookings b ON e.equipment_id=b.equipment_id GROUP BY c.category_id,c.category_name ORDER BY Bookings DESC"));most.doClick();}
    private void query(String sql){try(Connection c=DBConnection.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){ResultSetMetaData m=r.getMetaData();String[] cols=new String[m.getColumnCount()];for(int i=0;i<cols.length;i++)cols[i]=m.getColumnLabel(i+1);DefaultTableModel n=new DefaultTableModel(cols,0){public boolean isCellEditable(int a,int b){return false;}};while(r.next()){Object[] row=new Object[cols.length];for(int i=0;i<cols.length;i++)row[i]=r.getObject(i+1);n.addRow(row);}table.setModel(n);}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage());}}
}
